let Ownership=ApimClientOwnership_CL|summarize arg_max(TimeGenerated,*) by ClientId|project ClientId,Own_App=AppName,Own_Team=Team,Own_CC=CostCenter,Own_BU=BusinessUnit;
let Rates=ApimModelRate_CL|summarize arg_max(TimeGenerated,*) by ModelName;
let Base=ApimAiGateway_CL|where TimeGenerated {TimeRange}|lookup kind=leftouter Ownership on $left.Appid==$right.ClientId|extend Team=coalesce(Own_Team,'UNATTRIBUTED'),CostCenter=coalesce(iif(isempty(CostCenterClaim),tostring(Own_CC),CostCenterClaim),'UNKNOWN'),BusinessUnit=coalesce(iif(isempty(BusinessUnitClaim),tostring(Own_BU),BusinessUnitClaim),'UNKNOWN'),AppName=coalesce(Own_App,Appid),AttributionSource=iif(isnotempty(CostCenterClaim),'B:jwt-claim','A:lookup');
Base|summarize Requests=count(),Tokens=sum(TotalTokens),Errors=countif(IsError),Teams=dcountif(Team,Team!='UNATTRIBUTED')

let Ownership=ApimClientOwnership_CL|summarize arg_max(TimeGenerated,*) by ClientId|project ClientId,Own_App=AppName,Own_Team=Team,Own_CC=CostCenter,Own_BU=BusinessUnit;
let Rates=ApimModelRate_CL|summarize arg_max(TimeGenerated,*) by ModelName;
let Base=ApimAiGateway_CL|where TimeGenerated {TimeRange}|lookup kind=leftouter Ownership on $left.Appid==$right.ClientId|extend Team=coalesce(Own_Team,'UNATTRIBUTED'),CostCenter=coalesce(iif(isempty(CostCenterClaim),tostring(Own_CC),CostCenterClaim),'UNKNOWN'),BusinessUnit=coalesce(iif(isempty(BusinessUnitClaim),tostring(Own_BU),BusinessUnitClaim),'UNKNOWN'),AppName=coalesce(Own_App,Appid),AttributionSource=iif(isnotempty(CostCenterClaim),'B:jwt-claim','A:lookup');
Base|lookup kind=leftouter Rates on ModelName|extend EstCost=(todouble(PromptTokens-CachedPromptTokens)/1000.0)*InputPer1k+(todouble(CompletionTokens)/1000.0)*OutputPer1k|summarize EstCostUSD=round(sum(EstCost),4) by Team|sort by EstCostUSD desc

let Ownership=ApimClientOwnership_CL|summarize arg_max(TimeGenerated,*) by ClientId|project ClientId,Own_App=AppName,Own_Team=Team,Own_CC=CostCenter,Own_BU=BusinessUnit;
let Rates=ApimModelRate_CL|summarize arg_max(TimeGenerated,*) by ModelName;
let Base=ApimAiGateway_CL|where TimeGenerated {TimeRange}|lookup kind=leftouter Ownership on $left.Appid==$right.ClientId|extend Team=coalesce(Own_Team,'UNATTRIBUTED'),CostCenter=coalesce(iif(isempty(CostCenterClaim),tostring(Own_CC),CostCenterClaim),'UNKNOWN'),BusinessUnit=coalesce(iif(isempty(BusinessUnitClaim),tostring(Own_BU),BusinessUnitClaim),'UNKNOWN'),AppName=coalesce(Own_App,Appid),AttributionSource=iif(isnotempty(CostCenterClaim),'B:jwt-claim','A:lookup');
Base|summarize PromptTokens=sum(PromptTokens),CompletionTokens=sum(CompletionTokens) by ModelName|sort by PromptTokens desc

let Ownership=ApimClientOwnership_CL|summarize arg_max(TimeGenerated,*) by ClientId|project ClientId,Own_App=AppName,Own_Team=Team,Own_CC=CostCenter,Own_BU=BusinessUnit;
let Rates=ApimModelRate_CL|summarize arg_max(TimeGenerated,*) by ModelName;
let Base=ApimAiGateway_CL|where TimeGenerated {TimeRange}|lookup kind=leftouter Ownership on $left.Appid==$right.ClientId|extend Team=coalesce(Own_Team,'UNATTRIBUTED'),CostCenter=coalesce(iif(isempty(CostCenterClaim),tostring(Own_CC),CostCenterClaim),'UNKNOWN'),BusinessUnit=coalesce(iif(isempty(BusinessUnitClaim),tostring(Own_BU),BusinessUnitClaim),'UNKNOWN'),AppName=coalesce(Own_App,Appid),AttributionSource=iif(isnotempty(CostCenterClaim),'B:jwt-claim','A:lookup');
Base|lookup kind=leftouter Rates on ModelName|extend EstCost=(todouble(PromptTokens-CachedPromptTokens)/1000.0)*InputPer1k+(todouble(CompletionTokens)/1000.0)*OutputPer1k|summarize Requests=count(),TotalTokens=sum(TotalTokens),EstCostUSD=round(sum(EstCost),4) by Team,CostCenter,AttributionSource|sort by EstCostUSD desc

let Ownership=ApimClientOwnership_CL|summarize arg_max(TimeGenerated,*) by ClientId|project ClientId,Own_App=AppName,Own_Team=Team,Own_CC=CostCenter,Own_BU=BusinessUnit;
let Rates=ApimModelRate_CL|summarize arg_max(TimeGenerated,*) by ModelName;
let Base=ApimAiGateway_CL|where TimeGenerated {TimeRange}|lookup kind=leftouter Ownership on $left.Appid==$right.ClientId|extend Team=coalesce(Own_Team,'UNATTRIBUTED'),CostCenter=coalesce(iif(isempty(CostCenterClaim),tostring(Own_CC),CostCenterClaim),'UNKNOWN'),BusinessUnit=coalesce(iif(isempty(BusinessUnitClaim),tostring(Own_BU),BusinessUnitClaim),'UNKNOWN'),AppName=coalesce(Own_App,Appid),AttributionSource=iif(isnotempty(CostCenterClaim),'B:jwt-claim','A:lookup');
let Budgets=ApimTeamBudget_CL|summarize arg_max(TimeGenerated,*) by Team|project Team,MonthlyBudget;
Base|where startofmonth(TimeGenerated)==startofmonth(now())|lookup kind=leftouter Rates on ModelName|extend EstCost=(todouble(PromptTokens-CachedPromptTokens)/1000.0)*InputPer1k+(todouble(CompletionTokens)/1000.0)*OutputPer1k|summarize MtdCost=round(sum(EstCost),4) by Team|join kind=leftouter Budgets on Team|extend BurnPct=round(100.0*MtdCost/MonthlyBudget,1)|extend Status=case(BurnPct>=100,'OVER_BUDGET',BurnPct>=80,'WARN_80PCT','OK')|project Team,MtdCost,MonthlyBudget,BurnPct,Status|sort by BurnPct desc

let Ownership=ApimClientOwnership_CL|summarize arg_max(TimeGenerated,*) by ClientId|project ClientId,Own_App=AppName,Own_Team=Team,Own_CC=CostCenter,Own_BU=BusinessUnit;
let Rates=ApimModelRate_CL|summarize arg_max(TimeGenerated,*) by ModelName;
let Base=ApimAiGateway_CL|where TimeGenerated {TimeRange}|lookup kind=leftouter Ownership on $left.Appid==$right.ClientId|extend Team=coalesce(Own_Team,'UNATTRIBUTED'),CostCenter=coalesce(iif(isempty(CostCenterClaim),tostring(Own_CC),CostCenterClaim),'UNKNOWN'),BusinessUnit=coalesce(iif(isempty(BusinessUnitClaim),tostring(Own_BU),BusinessUnitClaim),'UNKNOWN'),AppName=coalesce(Own_App,Appid),AttributionSource=iif(isnotempty(CostCenterClaim),'B:jwt-claim','A:lookup');
Base|summarize Tokens=sum(TotalTokens) by bin(TimeGenerated,5m),Team

let Ownership=ApimClientOwnership_CL|summarize arg_max(TimeGenerated,*) by ClientId|project ClientId,Own_App=AppName,Own_Team=Team,Own_CC=CostCenter,Own_BU=BusinessUnit;
let Rates=ApimModelRate_CL|summarize arg_max(TimeGenerated,*) by ModelName;
let Base=ApimAiGateway_CL|where TimeGenerated {TimeRange}|lookup kind=leftouter Ownership on $left.Appid==$right.ClientId|extend Team=coalesce(Own_Team,'UNATTRIBUTED'),CostCenter=coalesce(iif(isempty(CostCenterClaim),tostring(Own_CC),CostCenterClaim),'UNKNOWN'),BusinessUnit=coalesce(iif(isempty(BusinessUnitClaim),tostring(Own_BU),BusinessUnitClaim),'UNKNOWN'),AppName=coalesce(Own_App,Appid),AttributionSource=iif(isnotempty(CostCenterClaim),'B:jwt-claim','A:lookup');
Base|where StatusCode==200|summarize Calls=count(),GatewayP50=round(percentile(TotalLatencyMs,50),0),GatewayP95=round(percentile(TotalLatencyMs,95),0),BackendP95=round(percentile(BackendLatencyMs,95),0) by ModelName|sort by GatewayP95 desc

let Ownership=ApimClientOwnership_CL|summarize arg_max(TimeGenerated,*) by ClientId|project ClientId,Own_App=AppName,Own_Team=Team,Own_CC=CostCenter,Own_BU=BusinessUnit;
let Rates=ApimModelRate_CL|summarize arg_max(TimeGenerated,*) by ModelName;
let Base=ApimAiGateway_CL|where TimeGenerated {TimeRange}|lookup kind=leftouter Ownership on $left.Appid==$right.ClientId|extend Team=coalesce(Own_Team,'UNATTRIBUTED'),CostCenter=coalesce(iif(isempty(CostCenterClaim),tostring(Own_CC),CostCenterClaim),'UNKNOWN'),BusinessUnit=coalesce(iif(isempty(BusinessUnitClaim),tostring(Own_BU),BusinessUnitClaim),'UNKNOWN'),AppName=coalesce(Own_App,Appid),AttributionSource=iif(isnotempty(CostCenterClaim),'B:jwt-claim','A:lookup');
Base|summarize Total=count(),Errors=countif(IsError),Http4xx=countif(StatusCode between (400 .. 499)),Http5xx=countif(StatusCode>=500) by ModelName,ErrorReason|extend ErrorRatePct=round(100.0*Errors/Total,2)|sort by Errors desc

let Ownership=ApimClientOwnership_CL|summarize arg_max(TimeGenerated,*) by ClientId|project ClientId,Own_App=AppName,Own_Team=Team,Own_CC=CostCenter,Own_BU=BusinessUnit;
let Rates=ApimModelRate_CL|summarize arg_max(TimeGenerated,*) by ModelName;
let Base=ApimAiGateway_CL|where TimeGenerated {TimeRange}|lookup kind=leftouter Ownership on $left.Appid==$right.ClientId|extend Team=coalesce(Own_Team,'UNATTRIBUTED'),CostCenter=coalesce(iif(isempty(CostCenterClaim),tostring(Own_CC),CostCenterClaim),'UNKNOWN'),BusinessUnit=coalesce(iif(isempty(BusinessUnitClaim),tostring(Own_BU),BusinessUnitClaim),'UNKNOWN'),AppName=coalesce(Own_App,Appid),AttributionSource=iif(isnotempty(CostCenterClaim),'B:jwt-claim','A:lookup');
Base|summarize Requests=count(),TotalTokens=sum(TotalTokens),LastSeen=max(TimeGenerated) by AppName,Appid,Team|top 25 by TotalTokens desc
